#define LIB_SYSTICK_CTRL (*(__IO uint32_t *)0xE000E010UL)
#define LIB_SYSTICK_LOAD (*(__IO uint32_t *)0xE000E014UL)
#define LIB_SYSTICK_VAL (*(__IO uint32_t *)0xE000E018UL)
#define LIB_NVIC_ISER ((__IO uint32_t *)0xE000E100UL)
#define LIB_NVIC_ICER ((__IO uint32_t *)0xE000E180UL)
#define LIB_NVIC_ICPR ((__IO uint32_t *)0xE000E280UL)
#define LIB_NVIC_IPR ((__IO uint32_t *)0xE000E400UL)
#define LIB_SCB_VTOR (*(__IO uint32_t *)0xE000ED08UL)

typedef int32_t IRQn_Type;

#define TC0_IRQn 55
#define TIM4_IRQn TC0_IRQn /* PLC cycle timer */
#define LIB_IRQ_COUNT 71

static inline void NVIC_EnableIRQ(IRQn_Type irq)
{
    LIB_NVIC_ISER[(uint32_t)irq >> 5] = 1UL << ((uint32_t)irq & 31U);
}
static inline void NVIC_DisableIRQ(IRQn_Type irq)
{
    LIB_NVIC_ICER[(uint32_t)irq >> 5] = 1UL << ((uint32_t)irq & 31U);
}
static inline void NVIC_ClearPendingIRQ(IRQn_Type irq)
{
    LIB_NVIC_ICPR[(uint32_t)irq >> 5] = 1UL << ((uint32_t)irq & 31U);
}
/* 2 bits of priority (0 = highest) in the upper bits of a byte; word access only on this core */
static inline void NVIC_SetPriority(IRQn_Type irq, uint32_t priority)
{
    uint32_t shift = ((uint32_t)irq & 3U) * 8U;
    uint32_t v = LIB_NVIC_IPR[(uint32_t)irq >> 2];

    v &= ~(0xFFUL << shift);
    v |= ((priority << 6) & 0xFFUL) << shift;
    LIB_NVIC_IPR[(uint32_t)irq >> 2] = v;
}

